MTM.visaFaq = [
 ["MM2H (Platinum / Gold / Silver)",[["What are the differences between MM2H Platinum, Gold, and Silver?","The tiers differ in financial thresholds, pass duration (15/10/5 years), and dependant coverage. Platinum allows extended family and domestic helpers; Silver covers spouse and children only. See the MM2H tab for a full comparison."],["Can I upgrade from Silver to Gold or Platinum later?","Yes, you may apply to upgrade your tier when you meet the higher financial requirements. You'll need to top up your fixed deposit and provide updated proof of income and assets."],["Can MM2H holders work in Malaysia?","No. MM2H is a social visit pass and does not permit local employment. However, you may continue remote work for overseas employers or invest in approved businesses."],["How much can I withdraw from my fixed deposit?","After one year, you may withdraw up to 50% of your fixed deposit for approved expenses such as property purchase, medical costs, or children's education in Malaysia."],["Is there a minimum stay requirement for MM2H?","The federal MM2H programme requires a minimum cumulative stay of 90 days per year. Failure to meet this may affect your renewal eligibility."]]],
 ["MM2H JS-SEZ (Johor Special Economic Zone)",[["How does MM2H SEZ differ from the federal MM2H?","The MM2H SEZ variant is specifically for the Johor-Singapore Special Economic Zone and is expected to offer lower financial thresholds than the federal programme while providing access to JS-SEZ benefits and incentives."],["Are the MM2H SEZ requirements finalised?","As of now, several requirements are still marked as expected/TBC. The programme is being developed alongside the broader JS-SEZ framework. Check official channels for the latest updates."],["Can I buy property under MM2H SEZ?","Property purchase eligibility under the SEZ variant is expected but the minimum threshold is yet to be confirmed. It may differ from the RM 600K minimum for federal MM2H."],["Does MM2H SEZ allow me to work in the JS-SEZ?","No. Like the federal MM2H, it is a social visit pass and does not permit local employment. A separate Employment Pass would be required to work locally."]]],
 ["MM2H Sabah (S-MM2H)",[["Is MM2H Sabah separate from the federal MM2H?","Yes. Sabah administers its own MM2H programme (S-MM2H) independently from the federal government, with its own application process, fees, and financial requirements, which are significantly lower."],["Is there a minimum age for Sabah MM2H?","No. Unlike the federal programme which requires applicants to be at least 35, Sabah's S-MM2H has no minimum age requirement."],["What is the property purchase threshold in Sabah?","S-MM2H holders may purchase property in Sabah valued at RM 500K and above, compared to RM 600K for the federal programme."],["Can I live anywhere in Malaysia with Sabah MM2H?","S-MM2H is intended for residence in Sabah. While you can travel freely within Malaysia, your primary residence should be in Sabah to maintain the pass."]]],
 ["MM2H Sarawak (S-MM2H)",[["Is MM2H Sarawak separate from the federal MM2H?","Yes. Sarawak has its own independently administered S-MM2H programme with lower financial requirements than the federal programme."],["Is there a minimum age for Sarawak MM2H?","No. Like Sabah, Sarawak's S-MM2H has no minimum age requirement for applicants."],["What is the property purchase threshold in Sarawak?","S-MM2H Sarawak holders may purchase property valued at RM 500K and above."],["Can I live outside Sarawak with this pass?","S-MM2H Sarawak is intended for residence in Sarawak. You can travel within Malaysia freely, but your primary residence should be in Sarawak."]]],
 ["PVIP (Premium Visa Integration Programme)",[["What makes PVIP different from MM2H Platinum?","PVIP is a 20-year pass with significantly higher financial requirements (RM 10M+ liquid assets) but offers unique privileges like the ability to invest, hold company directorships, and access fast-track government services, none of which are available under MM2H."],["Can PVIP holders work or invest in Malaysia?","Yes. Unlike MM2H, PVIP holders are permitted to invest in approved sectors and hold directorships in Malaysian companies."],["Who can I bring as dependants under PVIP?","PVIP offers the broadest dependant coverage: you can bring your spouse, children, parents, and in-laws."],["Is PVIP renewable after 20 years?","The PVIP is issued for a 20-year period. Renewal terms are subject to the prevailing regulations at the time of expiry."],["How much is the fixed deposit for PVIP?","PVIP requires a fixed deposit of RM 5 million, along with proof of RM 10 million+ in liquid assets and annual offshore income of RM 480K+."]]],
 ["DE Rantau (Digital Nomad Pass)",[["Is DE Rantau the same as the Digital Nomad Visa?","Yes. DE Rantau, the Digital Nomad Pass, and the Digital Nomad Visa all refer to the same programme administered by MDEC (Malaysia Digital Economy Corporation)."],["What income do I need for DE Rantau?","You need a minimum annual income of USD 24,000 from overseas clients or a foreign employer. Proof of employment contracts or freelance engagements is required."],["Can I bring my family on DE Rantau?","Yes. You can bring your spouse and children as dependants under the DE Rantau programme."],["Do I pay Malaysian tax on my foreign income?","No. DE Rantau holders are not subject to Malaysian income tax on their foreign-sourced income."],["How long can I stay on DE Rantau?","The initial pass is for 3–12 months and is renewable, allowing flexible extended stays in Malaysia."]]],
 ["Employment Pass (EP)",[["What is the minimum salary for an Employment Pass?","The minimum salary threshold is RM 5,000 per month. Higher salaries may qualify for longer pass durations (up to 5 years)."],["Can my spouse work on a dependant pass under my EP?","Spouses on a dependant pass tagged to an Employment Pass can apply for permission to work in Malaysia."],["Does my employer handle the EP application?","Yes. The sponsoring Malaysian company must be registered with the Expatriate Services Division (ESD) and will submit the application on your behalf."],["Can an Employment Pass lead to permanent residency?","Yes. Long-term Employment Pass holders may be eligible to apply for permanent residency (MyPR), though approval is discretionary and not guaranteed."],["What happens if I change employers?","You will need to apply for a new Employment Pass under your new employer. The previous pass is cancelled when you leave the sponsoring company."]]],
 ["Professional Visit Pass (PVP)",[["What activities can I do on a PVP?","PVP covers short-term professional activities such as consultancy, training, audits, technical installations, and project-based work, but not regular employment."],["How long is a PVP valid?","A PVP can be issued for up to 12 months, depending on the nature of the professional activity."],["Do I need a job offer for a PVP?","You need an invitation from a Malaysian entity (company or organisation) that details the professional purpose of your visit."],["Can a PVP be converted to an Employment Pass?","Not directly. If you wish to take up long-term employment, you'll need to apply separately for an Employment Pass through a sponsoring company."]]],
 ["Student Pass & Guardian Pass",[["Can students work part-time in Malaysia?","Yes. Student Pass holders are permitted to work part-time for up to 20 hours per week during semester breaks, subject to approval."],["What is the Guardian Pass and who can apply?","The Guardian Pass is issued to a parent or legal guardian and is tied to the child's Student Pass. It is only valid while the child's Student Pass is active."],["Can the guardian work on a Guardian Pass?","No. The Guardian Pass does not permit employment. It is solely for accompanying and caring for the child studying in Malaysia."],["How long is the Student Pass valid?","The Student Pass is issued for the duration of the study programme and is renewed as long as the student remains enrolled."],["Can I switch from a Student Pass to an Employment Pass?","Yes. Upon graduation, you may apply for an Employment Pass if you receive a job offer from a Malaysian company."]]]
];
